<script setup>
import { onMounted, ref, computed } from 'vue'
import { CalendarDays, UsersRound, Wallet, Star, TrendingUp, Pencil, ClipboardList, PlusCircle } from 'lucide-vue-next'
import OwnerTabs from '../components/OwnerTabs.vue'
import { ensureInstructor } from '../lib/instructor'
import { authRequest, state, money, notify } from '../lib/state'
const stats=ref(null),loading=ref(true),shown=ref('ocupacion'),selected=ref('all')
async function load(){try{await ensureInstructor();stats.value=await authRequest('/instructor/dashboard');}catch(e){notify(e.message)}finally{loading.value=false}}
onMounted(load)
const rows=computed(()=>stats.value?.byWorkshop?.filter(x=>selected.value==='all'||x.id===selected.value)||[])
</script>
<template><div class="page owner-page"><div class="owner-intro"><span class="avatar mid">{{state.user?.name?.charAt(0)||'M'}}</span><div><h1>{{state.user?.name || 'Panel del tallerista'}}</h1><p>Gestiona tus talleres y conoce tus resultados.</p></div><span class="owner-label">Modo Tallerista</span></div><OwnerTabs /><div v-if="!state.user?.studio?.displayName" class="card-note studio-cta"><b>Personaliza tu página de tallerista.</b> Responde una pregunta sobre la estética que quieres (o diseña todo tú) y agrega descripción, fotos y enlaces. <RouterLink to="/tallerista/perfil" class="btn primary sm">Personalizar ahora</RouterLink></div>
  <div v-if="loading" class="loading-area">Cargando indicadores...</div><template v-else-if="stats"><div class="metric-grid"><div class="metric"><CalendarDays/><span>TALLERES ACTIVOS</span><b>{{stats.activeWorkshops}}</b><small>publicaciones visibles</small></div><div class="metric"><UsersRound/><span>CUPOS RESERVADOS</span><b>{{stats.seatsReserved}}</b><small>en todos tus talleres</small></div><div class="metric"><Wallet/><span>INGRESO ESTIMADO</span><b>{{money(stats.estimatedGross)}}</b><small>reservas × precio; no son pagos</small></div><div class="metric"><Star/><span>CALIFICACIÓN MEDIA</span><b>{{stats.averageRating??'—'}}</b><small>{{stats.reviewCount}} reseñas</small></div></div>
  <section class="analytics-card"><div class="analytics-heading"><div><h2>Ocupación por sesión</h2><p class="muted small">Inscritos y monto recaudado estimado (reservas × precio) por sesión.</p></div><label class="inline-label">Taller<select v-model="selected"><option value="all">Todos</option><option v-for="w in stats.byWorkshop" :value="w.id" :key="w.id">{{w.title}}</option></select></label></div><div v-if="rows.length"><div v-for="row in rows" :key="row.id" class="occupancy-row"><div class="between"><strong>{{row.title}}</strong><span>{{row.reserved}}/{{row.capacity}} cupos · {{row.occupancy}}% · {{money(row.estimatedGross)}}{{row.enrollmentOpen?'':' · inscripciones cerradas'}}</span></div><div class="track"><div class="track-progress" :style="{width:`${row.occupancy}%`}"/></div></div></div><div v-else class="empty compact">No tienes publicaciones aún.</div><div class="small muted analytics-foot"><TrendingUp :size="16"/> Actualiza las reservas y regresa aquí para ver los indicadores modificados.</div></section>
  <div class="quick-action-grid"><RouterLink class="quick-action" to="/tallerista/publicar"><PlusCircle/><div><b>Publicar taller</b><span>Crea una ficha completa</span></div></RouterLink><RouterLink class="quick-action" to="/tallerista/agenda"><CalendarDays/><div><b>Revisar agenda</b><span>Consulta horarios disponibles</span></div></RouterLink><RouterLink class="quick-action" to="/tallerista/inscritos"><ClipboardList/><div><b>Ver inscripciones</b><span>Listado de personas registradas</span></div></RouterLink><RouterLink class="quick-action" to="/opinion"><Star/><div><b>Danos tu opinión</b><span>Ayúdanos a mejorar Hobbiz</span></div></RouterLink></div></template></div></template>
